import React from "react";
import SupervisorSidebar from "../componentsSupervisorSidebar";
import "./SupervisorDashboard.css";

const SupervisorDashboard = () => {
  return (
    <div className="supervisor-dashboard">
      {/* Sidebar */}
      <div className="supervisor-sidebar">
        <SupervisorSidebar />
      </div>

      {/* Main Content */}
      <div className="supervisor-main">
        <header className="supervisor-header">
          <h1>Welcome, Supervisor!</h1>
          <p>Manage projects, provide feedback, and track student progress all in one place.</p>
        </header>

        {/* Dashboard Features */}
        <div className="supervisor-features">
          <div className="feature-card">
            <h3>Feedback</h3>
            <p>Review and provide feedback on student projects.</p>
          </div>
          <div className="feature-card">
            <h3>Progress Tracking</h3>
            <p>Monitor the progress of assigned students and teams.</p>
          </div>
          <div className="feature-card">
            <h3>Schedule Meetings</h3>
            <p>Organize meetings with students or teams.</p>
          </div>
          <div className="feature-card">
            <h3>Reports</h3>
            <p>Generate detailed reports for projects.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SupervisorDashboard;
